#[no_mangle]
pub unsafe extern "C" fn zblock_substring_search(a:*const i64,length:usize)->i64{if a.is_null()||length<3{return -1;}let v=std::slice::from_raw_parts(a,length);let tn=v[0];let pn=v[1];if tn<0||tn>256||pn<1||pn>64||length!=(tn+pn+2)as usize{return -1;}if v[2..].iter().any(|&x|!(0..=127).contains(&x)||x==36){return -1;}let sep=pn as usize;let n=(tn+pn+1)as usize;let mut s=[0i64;321];let mut z=[0usize;321];s[..sep].copy_from_slice(&v[2+tn as usize..2+tn as usize+sep]);s[sep]=-1;s[sep+1..n].copy_from_slice(&v[2..2+tn as usize]);let(mut l,mut r)=(0usize,0usize);for i in 1..n{z[i]=if i<=r{(r-i+1).min(z[i-l])}else{0};while i+z[i]<n&&s[z[i]]==s[i+z[i]]{z[i]+=1;}if i+z[i]>0&&i+z[i]-1>r{l=i;r=i+z[i]-1;}}z[sep+1..n].iter().filter(|&&x|x>=sep).count()as i64}
